class SemanticQualityValidator:
    """의미적 품질 검증기"""

    def __init__(self):
        self.embeddings = OpenAIEmbeddings()
        self.similarity_threshold = 0.7

    def validate_keyword_relevance(self, keywords, document_text):
        """키워드-문서 관련성 검증"""

        # 문서와 키워드 임베딩 생성
        doc_embedding = self.embeddings.embed_query(document_text[:2000])
        keyword_text = " ".join(keywords)
        keyword_embedding = self.embeddings.embed_query(keyword_text)

        # 코사인 유사도 계산
        similarity = cosine_similarity([doc_embedding], [keyword_embedding])[0][0]

        return {
            "similarity_score": similarity,
            "is_relevant": similarity > self.similarity_threshold,
            "keywords_count": len(keywords),
            "quality_level": self._get_quality_level(similarity)
        }

    def validate_summary_coherence(self, summary, document_text):
        """요약 일관성 검증"""

        # 요약과 원문의 주요 주제 추출
        doc_topics = self._extract_topics(document_text)
        summary_topics = self._extract_topics(summary)

        # 주제 중첩도 계산
        topic_overlap = len(set(doc_topics) & set(summary_topics)) / len(set(doc_topics) | set(summary_topics))

        return {
            "topic_overlap": topic_overlap,
            "coherence_score": topic_overlap,
            "is_coherent": topic_overlap > 0.5,
            "summary_length": len(summary),
            "density_score": len(summary.split()) / len(summary)
        }

    def _extract_topics(self, text):
        """텍스트에서 주요 주제 추출"""
        # 간단한 TF-IDF 기반 주제 추출
        from sklearn.feature_extraction.text import TfidfVectorizer

        vectorizer = TfidfVectorizer(max_features=10, stop_words='english')
        try:
            tfidf_matrix = vectorizer.fit_transform([text])
            feature_names = vectorizer.get_feature_names_out()
            return list(feature_names)
        except:
            return []

    def _get_quality_level(self, score):
        """점수를 품질 레벨로 변환"""
        if score >= 0.9:
            return "excellent"
        elif score >= 0.7:
            return "good"
        elif score >= 0.5:
            return "acceptable"
        else:
            return "poor"
